function exerciseTargets(exOrName){
 const name=typeof exOrName==="string"?exOrName:exOrName.name,L=lib(name),p=L.pattern;
 let primary=L.primary||"Mobility",secondary=[];
 if(p==="incline_press")primary="Upper Chest",secondary=["Front Delts","Triceps"];
 else if(p==="decline_press")primary="Lower Chest",secondary=["Triceps","Front Delts"];
 else if(p==="horizontal_press")primary="Mid Chest",secondary=["Front Delts","Triceps"];
 else if(p==="chest_fly"){
  primary=/low-to-high/i.test(name)?"Upper Chest":/high-to-low/i.test(name)?"Lower Chest":"Mid Chest";secondary=["Front Delts"];
 }
 else if(p==="vertical_pull")primary="Lats",secondary=["Biceps","Brachialis","Upper Back"];
 else if(p==="lat_isolation")primary="Lats",secondary=["Upper Back"];
 else if(p==="horizontal_row")primary="Mid Back",secondary=["Lats","Rear Delts","Biceps"];
 else if(p==="upper_back_row")primary="Upper Back",secondary=["Rear Delts","Biceps"];
 else if(p==="shoulder_press")primary="Front Delts",secondary=["Side Delts","Triceps"];
 else if(p==="lateral_raise"||p==="scaption")primary="Side Delts",secondary=["Traps"];
 else if(p==="front_raise")primary="Front Delts",secondary=["Side Delts"];
 else if(p==="rear_delt")primary="Rear Delts",secondary=["Upper Back","Traps"];
 else if(p==="external_rotation")primary="Rotator Cuff",secondary=["Rear Delts"];
 else if(p==="shrug")primary="Traps",secondary=["Forearms"];
 else if(p==="biceps_lengthened"||p==="biceps_preacher"||p==="biceps_curl")primary="Biceps",secondary=["Brachialis","Forearms"];
 else if(p==="hammer_curl")primary="Brachialis",secondary=["Biceps","Forearms"];
 else if(p==="triceps_overhead")primary="Triceps Long Head",secondary=["Triceps"];
 else if(p==="triceps_pushdown")primary="Triceps Lateral/Medial",secondary=["Triceps"];
 else if(p==="triceps_press")primary="Triceps",secondary=["Front Delts","Mid Chest"];
 else if(p==="knee_dominant"||p==="leg_extension")primary="Quads",secondary=["Glutes","Adductors"];
 else if(p==="single_leg")primary="Quads",secondary=["Glutes","Hamstrings"];
 else if(p==="hip_hinge")primary="Hamstrings",secondary=["Glutes","Spinal Erectors"];
 else if(p==="leg_curl")primary="Hamstrings",secondary=["Calves"];
 else if(p==="hip_extension")primary="Glutes",secondary=["Hamstrings"];
 else if(p==="hip_abduction")primary="Glute Medius",secondary=["Glutes"];
 else if(p==="hip_adduction")primary="Adductors",secondary=["Glutes"];
 else if(p==="calf_raise")primary="Calves",secondary=[];
 else if(p==="spinal_flexion")primary="Abs",secondary=["Obliques"];
 else if(p==="reverse_crunch"||p==="leg_raise")primary="Abs (lower emphasis)",secondary=["Deep Core"];
 else if(p==="anti_extension"||p==="stability")primary="Deep Core",secondary=["Abs","Obliques"];
 else if(p==="anti_rotation"||p==="anti_lateral_flexion"||p==="rotation")primary="Obliques",secondary=["Deep Core"];
 else if(p==="carry"||p==="grip"||p==="wrist_extension"||p==="wrist_flexion")primary="Forearms",secondary=["Grip"];
 else if(["zone2","intervals","conditioning"].includes(p)||L.kind==="cardio")primary="Cardio",secondary=[];
 else if(L.kind==="mobility"||["full_body_mobility","shoulder_mobility","hip_mobility","ankle_mobility","ankle_hip_mobility","hamstring_mobility","spine_mobility","yoga_pose","breathing"].includes(p))primary="Mobility",secondary=[];
 else if(L.primary==="Shoulder Health")primary="Rotator Cuff",secondary=["Rear Delts"];
 else if(L.primary==="Core")primary="Deep Core",secondary=["Abs","Obliques"];
 else if(L.primary==="Abs")primary="Abs",secondary=["Deep Core"];
 else if(L.primary==="Back")primary="Lats",secondary=["Upper Back"];
 else if(L.primary==="Shoulders")primary="Side Delts",secondary=["Front Delts","Rear Delts"];
 else if(L.primary==="Triceps")primary="Triceps",secondary=[];
 else if(L.primary==="Biceps")primary="Biceps",secondary=["Brachialis"];
 else primary=L.primary||"Mobility";
 return {primary,secondary:[...new Set(secondary)].filter(x=>x!==primary),info:MUSCLE_INFO[primary]||{id:"mobility",anatomy:primary,view:"front"}};
}

