 if(id==="adductors")add('<path d="M56 77 L60 77 L58 101 L53 101Z"/><path d="M60 77 L64 77 L67 101 L62 101Z"/>');
 if(id==="abs"||id==="lower-abs"||id==="core")add('<rect x="52" y="50" width="16" height="25" rx="5"/>');
 if(id==="lower-abs")add('<rect x="52" y="64" width="16" height="12" rx="4"/>');
