 if(id==="mobility"||id==="rehab")add('<circle cx="60" cy="60" r="20" opacity=".35"/><path d="M44 64 Q60 43 76 64" fill="none" stroke="'+pink+'" stroke-width="4" stroke-linecap="round"/>');
 const highlight=hi.join("");
 return `<svg viewBox="0 0 120 120" role="img" aria-label="${esc(label)}"><defs><linearGradient id="bg${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#141414"/><stop offset="1" stop-color="#080808"/></linearGradient></defs><rect width="120" height="120" rx="16" fill="url(#bg${id})"/><g opacity=".98"><circle cx="60" cy="17" r="9" fill="${body}"/><path d="M49 28 Q60 24 71 28 L78 56 L72 76 L69 78 L73 110 L64 110 L60 79 L56 110 L47 110 L51 78 L48 76 L42 56Z" fill="${body}" stroke="${line}" stroke-width="1.2"/><path d="M48 34 L34 42 L24 72 L30 75 L41 53Z" fill="${body2}" stroke="${line}" stroke-width="1"/><path d="M72 34 L86 42 L96 72 L90 75 L79 53Z" fill="${body2}" stroke="${line}" stroke-width="1"/></g><g fill="${red}" stroke="${pink}" stroke-width=".8" opacity=".95">${highlight}</g>${back?'<path d="M53 30 Q60 35 67 30" fill="none" stroke="#555" stroke-width="1"/>':''}<text x="60" y="116" text-anchor="middle" font-size="${compact?0:7}" fill="#d9d9dc" font-family="-apple-system,Segoe UI,Arial">${compact?"":esc(label)}</text></svg>`;
