function workoutMuscleFocus(){
 const map={};
 for(const e of effectivePlanExercises(activeDay)){
  const L=lib(e.name);if(isTimedKind(L.kind))continue;
  const t=exerciseTargets(e),sets=num(e.sets)||1;
  map[t.primary]=(map[t.primary]||0)+sets;
 }
 return Object.entries(map).sort((a,b)=>b[1]-a[1]);
}
function renderMuscleFocus(){
 const el=$("muscleFocus"),focus=workoutMuscleFocus();
 if(!el)return;
 if(!focus.length){el.innerHTML="";return}
 const all=effectivePlanExercises(activeDay).flatMap(e=>exerciseTargets(e).secondary||[]);
 const secs=[...new Set(all)].slice(0,5);
 el.innerHTML=`<div class="muscleFocusHead"><h3>Muscle Focus</h3><span>direct work by exact region</span></div><div class="muscleStrip">${focus.map(([name,sets])=>`<div class="muscleCard"><div class="muscleCardVisual">${muscleSvg(name,true)}</div><b>${esc(name)}</b><small>${sets} direct set${sets===1?"":"s"}</small><span class="anatomy">${esc((MUSCLE_INFO[name]||{}).anatomy||name)}</span></div>`).join("")}</div>${secs.length?`<div class="workoutCoverageNote">Secondary involvement: ${secs.map(esc).join(" · ")}</div>`:""}`;
}
function programCode(p){
 const n=(p?.name||"Plan").replace(/[^A-Za-z ]/g,"").trim().split(/\s+/);
 return (n[0]?.[0]||"P")+(n[1]?.[0]||"");
}

function iconFor(ex){return muscleSvg(exerciseTargets(ex).primary,true)}

function renderWeek(){
 const p=activeProgram();$("week").innerHTML=DAYS.map(d=>`<button class="day ${d===activeDay?"active":""}" onclick="setDay('${d}')"><div class="d">${d.toUpperCase()}</div><div class="n">${esc(dayBlock(p,d).name)}</div></button>`).join("")
}
window.setDay=d=>{activeDay=d;renderAll()}
function renderHero(){
 const p=activeProgram(),exs=currentExercises(),done=exs.reduce((a,e)=>a+e.rows.filter(r=>r.done).length,0),total=exs.reduce((a,e)=>a+e.rows.length,0);
 $("programLabel").textContent=p.name.toUpperCase();$("heroName").textContent=dayBlock(p,activeDay).name;$("progress").textContent=`${done} / ${total}`;
 $("heroMeta").textContent=exs.length?`${exs.length} exercises · ~${estimateMinutes(effectivePlanExercises(activeDay))} min · ${p.weeks}`:"Recovery day";
 $("exerciseCount").textContent=exs.length?`${exs.length} exercises`:"Rest";
 $("startBtn").style.display=exs.length?"block":"none";$("finishBtn").style.display=activeWorkout&&activeWorkout.programId===activeProgramId&&activeWorkout.day===activeDay?"block":"none";
 $("startBtn").textContent=activeWorkout&&activeWorkout.programId===activeProgramId&&activeWorkout.day===activeDay?`Workout in progress · ${activeWorkout.readiness}`:"▶ Start Smart Workout";
 const ds=deloadSignal();$("deload").className="notice"+(ds?" show":"");$("deload").textContent=ds;renderMuscleFocus()
}
function renderExercises(){
 const exs=currentExercises(),list=$("exerciseList");if(!exs.length){list.innerHTML='<div class="empty">Recovery day. You can switch programs or use a mobility session from Programs.</div>';return}
 list.innerHTML=exs.map((ex,i)=>{
  const L=lib(ex.name),rec=recommendation(ex),done=ex.rows.filter(r=>r.done).length,warm=warmups(ex,rec.weight);
  let body="";
  if(isTimedKind(L.kind)){
   const r=ex.rows[0]||{result:"",done:false};
   body=`<div class="coach"><div class="coachTop"><span>${rec.tag}</span><span>${L.kind.toUpperCase()}</span></div><div class="coachMsg">${esc(rec.msg)}</div></div>
   <div class="timedRow"><div class="timedTarget"><b>Target: ${esc(ex.reps)}</b><span>${esc(L.tip)}</span></div><input class="inp" placeholder="Result" value="${esc(r.result)}" onchange="setTimedResult(${i},this.value)"><button class="check ${r.done?"done":""}" onclick="completeSet(${i},0)">${r.done?"✓":"○"}</button></div>`;
  }else{
   const rows=ex.rows.map((r,j)=>`<div class="setRow"><div class="setNo">${j+1}</div><input class="inp" inputmode="decimal" placeholder="kg" value="${esc(r.weight)}" onchange="setVal(${i},${j},'weight',this.value)"><input class="inp" inputmode="numeric" placeholder="${esc(ex.reps)}" value="${esc(r.reps)}" onchange="setVal(${i},${j},'reps',this.value)"><select class="rir" onchange="setVal(${i},${j},'rir',this.value)"><option value="">RIR</option>${[0,1,2,3,4].map(v=>`<option value="${v}" ${String(r.rir)===String(v)?"selected":""}>${v}</option>`).join("")}</select><button class="check ${r.done?"done":""}" onclick="completeSet(${i},${j})">${r.done?"✓":"○"}</button></div>`).join("");
   body=`<div class="coach"><div class="coachTop"><span>SMART COACH · ${rec.tag}</span><span>${L.kind.toUpperCase()}</span></div><div class="coachMsg">${esc(rec.msg)}</div><div class="last">${esc(rec.last)}</div>${warm?`<div class="warm">Warm-up: ${warm}</div>`:""}${rec.weight?`<button class="coachBtn" onclick="applyWeight(${i},${rec.weight})">Use ${rec.weight} kg for empty sets</button>`:""}</div><div class="setHead"><div>SET</div><div>KG</div><div>REPS</div><div>RIR</div><div></div></div>${rows}`;
  }
  return `<div class="exercise ${i===0?"open":""} ${ex.optional?"optional":""}" id="ex${i}"><div class="exTop"><div class="exIcon">${iconFor(ex)}</div><div><div class="exName">${esc(ex.name)}${ex._addon?'<span class="tag addon">ADD-ON</span>':""}${ex.optional?'<span class="tag optional">OPTIONAL TODAY</span>':""}</div><div class="exMeta">${ex.sets} set${num(ex.sets)===1?"":"s"} · ${esc(ex.reps)} · ${ex.rest?ex.rest+"s":"no set rest"} · ${esc(L.equipment)}</div><div class="targetLine"><b>PRIMARY</b>${esc(exerciseTargets(ex).primary)}${exerciseTargets(ex).secondary.length?`<span class="secondaryText">Secondary · ${exerciseTargets(ex).secondary.map(esc).join(" · ")}</span>`:""}</div><div class="machine"><span class="machineLabel">MACHINE</span>${esc((machineMemory[ex.name]?.machine)||ex.machine||"Save machine / seat / station")}</div></div><button class="arrow" onclick="toggleEx(${i})">${done===ex.rows.length?"✓":"⌄"}</button></div><div class="exBody">${body}<div class="grid2"><div class="field"><label>Machine / station / seat</label><input value="${esc(machineMemory[ex.name]?.machine||ex.machine||"")}" onchange="setMachine(${i},'machine',this.value)"></div><div class="field"><label>Rest seconds</label><input inputmode="numeric" value="${esc(ex.rest||0)}" onchange="setExerciseRest(${i},this.value)"></div></div><div class="field" style="margin-top:7px"><label>Personal setup notes</label><textarea onchange="setMachine(${i},'notes',this.value)" placeholder="Seat 4, pin 6, grip, bench angle...">${esc(machineMemory[ex.name]?.notes||ex.notes||"")}</textarea></div><div class="actions"><button onclick="showHistory(${i})">History</button><button onclick="showTips(${i})">Details</button><button onclick="openSwap(${i})">Swap</button><button onclick="editToday(${i})">Edit Today</button></div></div></div>`
 }).join("")
}
window.toggleEx=i=>$("ex"+i).classList.toggle("open");
function requireWorkout(){if(!activeWorkout||activeWorkout.programId!==activeProgramId||activeWorkout.day!==activeDay){toast("Start the workout first");return false}return true}
window.setVal=(i,j,f,v)=>{if(!requireWorkout())return;activeWorkout.exercises[i].rows[j][f]=v;save(K.activeWorkout,activeWorkout)}
window.setTimedResult=(i,v)=>{if(!requireWorkout())return;activeWorkout.exercises[i].rows[0].result=v;save(K.activeWorkout,activeWorkout)}
window.setMachine=(i,f,v)=>{let ex=currentExercises()[i];if(!machineMemory[ex.name])machineMemory[ex.name]={machine:"",notes:""};machineMemory[ex.name][f]=v;save(K.machine,machineMemory);if(activeWorkout&&activeWorkout.programId===activeProgramId&&activeWorkout.day===activeDay){activeWorkout.exercises[i][f]=v;save(K.activeWorkout,activeWorkout)}renderExercises()}
window.setExerciseRest=(i,v)=>{if(activeWorkout&&activeWorkout.programId===activeProgramId&&activeWorkout.day===activeDay){activeWorkout.exercises[i].rest=num(v);save(K.activeWorkout,activeWorkout)}else toast("Rest edited for today's active workout only")}
window.applyWeight=(i,w)=>{if(!requireWorkout())return;activeWorkout.exercises[i].rows.forEach(r=>{if(!r.weight)r.weight=w});save(K.activeWorkout,activeWorkout);renderExercises();toast("Coach target applied")}
window.completeSet=(i,j)=>{
 if(!requireWorkout())return;let ex=activeWorkout.exercises[i],r=ex.rows[j];r.done=!r.done;save(K.activeWorkout,activeWorkout);renderHero();renderExercises();
 if(r.done){let next=findNext(i,j),rest=smartRest(ex,r.rir);if(next&&rest>0&&!isTimedKind(lib(ex.name).kind))startTimer(rest,next);else if(next&&rest<=0)focusNext(next);else if(!next)toast("All planned work complete")}
}
function findNext(i,j){
 for(let a=i;a<activeWorkout.exercises.length;a++){let e=activeWorkout.exercises[a];if(e.optional)continue;for(let b=(a===i?j+1:0);b<e.rows.length;b++)if(!e.rows[b].done)return {i:a,j:b,ex:e}}
 for(let a=0;a<activeWorkout.exercises.length;a++)for(let b=0;b<activeWorkout.exercises[a].rows.length;b++)if(!activeWorkout.exercises[a].rows[b].done)return {i:a,j:b,ex:activeWorkout.exercises[a]};
 return null
}
function focusNext(next){setTimeout(()=>{let el=$("ex"+next.i);if(el){el.classList.add("open");el.scrollIntoView({behavior:"smooth",block:"center"})}},100)}
function startTimer(sec,next){
 if(timer)clearInterval(timer);timerLeft=sec;timerTotal=sec;timerPaused=false;timerNext=next;$("timerOverlay").classList.add("show");$("pauseTimerBtn").textContent="Pause";drawTimer();
 let rec=recommendation(next.ex);$("nextInfo").innerHTML=`<b>NEXT → ${esc(next.ex.name)} · Set ${next.j+1}</b><br><span class="meta"><span class="machineLabel">MACHINE</span>${esc(machineMemory[next.ex.name]?.machine||next.ex.machine||"Machine/station not saved yet")}</span><br><span class="meta">Target: ${esc(next.ex.reps)}${rec.weight?` · Coach ${rec.weight} kg`:""}</span>`;
 timer=setInterval(()=>{if(!timerPaused){timerLeft--;drawTimer();if(timerLeft<=0)endTimer()}},1000)
}
function drawTimer(){let m=Math.floor(Math.max(0,timerLeft)/60),s=Math.max(0,timerLeft)%60;$("timerText").textContent=`${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;$("timerCircle").style.setProperty("--p",(Math.max(0,timerLeft)/timerTotal*100)+"%")}
window.toggleTimer=()=>{timerPaused=!timerPaused;$("pauseTimerBtn").textContent=timerPaused?"Resume":"Pause"}
window.addTimerTime=s=>{timerLeft+=s;timerTotal+=s;drawTimer()}
window.skipTimer=()=>{if(timer)clearInterval(timer);$("timerOverlay").classList.remove("show");if(timerNext)focusNext(timerNext)}
function endTimer(){if(timer)clearInterval(timer);$("timerOverlay").classList.remove("show");if(navigator.vibrate)navigator.vibrate([140,70,140]);if(timerNext)focusNext(timerNext);toast("Rest finished")}

window.openSmartStart=()=>{
 const p=activeProgram();openModal("Smart Start",`<p class="meta">${esc(p.name)} · ${esc(dayBlock(p,activeDay).name)}</p><div class="secHead"><h3>Readiness</h3></div><div class="choiceGrid">${["Great","Normal","Tired"].map(x=>`<button class="choice ${x==="Normal"?"active":""}" data-read="${x}" onclick="pickRead(this)">${x}</button>`).join("")}</div><div class="field"><label>Time available today</label><select id="startMinutes">${[20,30,45,60,75,90].map(x=>`<option ${x===60?"selected":""}>${x}</option>`).join("")}</select></div><button class="primary" onclick="startWorkout()">Start Workout</button>`)
}
window.pickRead=b=>{document.querySelectorAll("[data-read]").forEach(x=>x.classList.remove("active"));b.classList.add("active")}
window.startWorkout=()=>{
 let readiness=document.querySelector("[data-read].active")?.dataset.read||"Normal",mins=num($("startMinutes").value)||60;
 let exs=effectivePlanExercises(activeDay).map(e=>Object.assign(e,{rows:Array.from({length:Math.max(1,num(e.sets)||1)},()=>({weight:"",reps:"",rir:"",result:"",done:false}))}));
 exs=applyTimeBudget(exs,mins);activeWorkout={programId:activeProgramId,programName:activeProgram().name,day:activeDay,start:Date.now(),readiness,minutes:mins,exercises:exs};save(K.activeWorkout,activeWorkout);closeModal();renderAll();toast("Smart workout started")
}
window.finishWorkout=()=>{
 if(!requireWorkout())return;
 let completed=0,volume=0,prs=0,detail=activeWorkout.exercises.map(e=>{
  const L=lib(e.name);let sets=e.rows.filter(r=>r.done).map(r=>{
   completed++;if(!isTimedKind(L.kind))volume+=num(r.weight)*num(r.reps);
   let est=e1rm(r.weight,r.reps);if(est>bestHistoricalE1RM(e.name))prs++;
   return {weight:num(r.weight),reps:num(r.reps),rir:r.rir,result:r.result||"",e1rm:est}
  });return {name:e.name,kind:L.kind,primary:L.primary,sets,machine:machineMemory[e.name]?.machine||e.machine||"",notes:machineMemory[e.name]?.notes||e.notes||"",reps:e.reps}
 });
 let perf=performanceIndex(detail),prev=history.find(h=>h.programId===activeProgramId&&h.day===activeDay),vDelta=prev&&prev.volume?Math.round((volume-prev.volume)/prev.volume*100):null,pDelta=prev&&prev.performance?Math.round((perf-prev.performance)/prev.performance*100):null;
 let analysis=prev?`${volume&&prev.volume?`Volume ${vDelta>=0?"+":""}${vDelta}% vs previous ${dayBlock(activeProgram(),activeDay).name}. `:""}${perf&&prev.performance?`Compound performance ${pDelta>=0?"+":""}${pDelta}%. `:""}${prs?`${prs} estimated PR set${prs>1?"s":""}.`:"Session completed with no new estimated PR."}`:`Baseline saved for ${activeProgram().name}. The coach will use it for future targets.`;
 history.unshift({date:new Date().toISOString(),programId:activeProgramId,programName:activeProgram().name,day:activeDay,name:dayBlock(activeProgram(),activeDay).name,readiness:activeWorkout.readiness,minutes:Math.max(1,Math.round((Date.now()-activeWorkout.start)/60000)),sets:completed,volume:Math.round(volume),performance:perf,prs,analysis,exercises:detail});history=history.slice(0,200);save(K.history,history);
 activeWorkout=null;localStorage.removeItem(K.activeWorkout);renderAll();toast("Workout saved & analysed")
}

function renderPrograms(){
 const p=activeProgram(),locked=isLocked();
 $("activeProgramCard").innerHTML=`<div class="programHero"><div class="programHeroTop"><div><div class="eyebrow">ACTIVE PROGRAM</div><h2><span class="programMark">${esc(programCode(p))}</span>${esc(p.name)}</h2><div class="goal">${esc(p.goal)}</div></div><div class="meta">${esc(p.weeks||"")}</div></div><div class="programActions"><button onclick="openProgramSwitcher()">Switch Program</button><button onclick="duplicateProgram('${esc(activeProgramId)}')">${locked?"Customize a Copy":"Duplicate Plan"}</button></div>${locked?'<div class="lockedNote">This built-in program is protected. Add / Swap / Edit automatically creates a personal copy, so the original can never be lost.</div>':""}</div>`;
 renderAddons();renderSchedule();renderSaved();renderProgramLibrary();renderSettings()
}
function renderAddons(){
 let st=ensureAddonState();$("addonList").innerHTML=Object.values(ADDONS).map(a=>`<div class="addonCard"><div><b><span class="addonMark">${esc(programCode(a))}</span>${esc(a.name)}</b><p>${esc(a.description)}</p></div><button class="switch ${st[a.id]?"on":""}" onclick="toggleAddon('${a.id}')"></button></div>`).join("")
}
window.toggleAddon=id=>{let st=ensureAddonState();st[id]=!st[id];save(K.addons,addonState);renderAll();toast(st[id]?"Module enabled":"Module disabled")}
function renderSchedule(){
 const p=activeProgram();$("scheduleList").innerHTML=DAYS.map((d,di)=>{
  let b=dayBlock(p,d),items=b.exercises||[];return `<div class="planDay ${d===activeDay?"open":""}" id="pd${d}"><div class="planDayHead" onclick="togglePlanDay('${d}')"><b>${d} · ${esc(b.name)}</b><span class="meta">${items.length} exercises</span></div><div class="planDayBody">${items.length?items.map((e,i)=>`<div class="planItem"><div><b>${i+1}. ${esc(e.name)}</b><small>${e.sets} sets · ${esc(e.reps)} · ${e.rest||0}s · ${esc(lib(e.name).equipment)}</small></div><div class="mini"><button onclick="event.stopPropagation();openSwapPlan('${d}',${i})">Swap</button><button onclick="event.stopPropagation();editPlanExercise('${d}',${i})">Edit</button></div></div>`).join(""):'<div class="empty">Rest / recovery day</div>'}<button class="link" onclick="openAddExercise('${d}')">+ Add Exercise</button></div></div>`
 }).join("")
}
window.togglePlanDay=d=>$("pd"+d).classList.toggle("open")
function renderSaved(){
 const arr=Object.values(customs);$("savedList").innerHTML=arr.length?arr.map(p=>`<div class="programCard"><div class="programCardTop"><div><h4><span class="programMark">${esc(programCode(p))}</span>${esc(p.name)}</h4><p>${esc(p.goal||"Personal saved program")}</p></div><span class="meta">${p.id===activeProgramId?"ACTIVE":""}</span></div><div class="programButtons"><button class="activate" onclick="switchProgram('${p.id}')">${p.id===activeProgramId?"Active":"Activate"}</button><button onclick="duplicateProgram('${p.id}')">Duplicate</button>${p.id!=="my_5day"?`<button onclick="deleteProgram('${p.id}')">Delete</button>`:""}</div></div>`).join(""):'<div class="empty">No personal copies yet.</div>'
}
function renderProgramLibrary(){
 $("programLibrary").innerHTML=Object.values(BUILTINS).map(p=>`<div class="programCard"><div class="programCardTop"><div><h4><span class="programMark">${esc(programCode(p))}</span>${esc(p.name)}</h4><p>${esc(p.goal)}</p></div><span class="meta">${esc(p.weeks)}</span></div><div class="programButtons"><button class="activate" onclick="switchProgram('${p.id}')">${p.id===activeProgramId?"Active":"Use Program"}</button><button onclick="duplicateProgram('${p.id}')">Customize Copy</button></div></div>`).join("")
}
function renderSettings(){
 const c=programCoach();$("settings").innerHTML=`<div class="settings"><label>Weight increment (kg)<input id="prefInc" value="${prefs.increment}"></label><label>Target RIR<select id="prefRir">${[1,2,3].map(x=>`<option ${num(c.targetRir)===x?"selected":""}>${x}</option>`).join("")}</select></label><label>Compound rest override<select id="prefComp"><option value="">Program default</option>${[120,150,180,210].map(x=>`<option value="${x}" ${num(prefs.compoundRest)===x?"selected":""}>${x}s</option>`).join("")}</select></label><label>Isolation rest override<select id="prefIso"><option value="">Program default</option>${[60,75,90,120].map(x=>`<option value="${x}" ${num(prefs.isolationRest)===x?"selected":""}>${x}s</option>`).join("")}</select></label><button class="primary small" onclick="saveSettings()">Save Settings</button></div>`
}
window.saveSettings=()=>{prefs.increment=num($("prefInc").value)||2.5;prefs.targetRir=num($("prefRir").value)||2;prefs.compoundRest=$("prefComp").value?num($("prefComp").value):null;prefs.isolationRest=$("prefIso").value?num($("prefIso").value):null;save(K.prefs,prefs);renderAll();toast("Coach settings saved")}

function cancelWorkoutIfSwitch(){
 if(!activeWorkout)return true;if(confirm("A workout is in progress. Switch program and discard the unfinished workout?")){activeWorkout=null;localStorage.removeItem(K.activeWorkout);return true}return false
}
window.switchProgram=id=>{if(!cancelWorkoutIfSwitch())return;activeProgramId=id;localStorage.setItem(K.activeProgram,id);activeDay=DAYS[new Date().getDay()];renderAll();toast("Program switched")}
window.duplicateProgram=id=>{
 const src=getProgram(id),nid=uid("plan"),cp=clone(src);cp.id=nid;cp.name=(src.name.startsWith("Original")?"My 5-Day Split":src.name)+" – My Copy";cp.locked=false;cp.source=id;customs[nid]=cp;save(K.customs,customs);switchProgram(nid)
}
window.deleteProgram=id=>{if(id==="my_5day")return;if(!confirm("Delete this saved plan? Workout history will remain."))return;delete customs[id];save(K.customs,customs);if(activeProgramId===id)switchProgram("my_5day");renderAll()}
window.openProgramSwitcher=()=>openModal("Choose Program",`<p class="meta">Switching programs never deletes your saved plans, history, machine settings or PRs.</p>${Object.values(BUILTINS).map(p=>`<button class="swapItem" onclick="closeModal();switchProgram('${p.id}')"><b><span class="programMark">${esc(programCode(p))}</span>${esc(p.name)}</b><small>${esc(p.category)} · ${esc(p.weeks)}</small></button>`).join("")}${Object.values(customs).map(p=>`<button class="swapItem" onclick="closeModal();switchProgram('${p.id}')"><b><span class="programMark">SP</span>${esc(p.name)}</b><small>Saved plan</small></button>`).join("")}`)

function ensureEditable(){
 if(customs[activeProgramId])return activeProgramId;
 const src=activeProgram(),nid=uid("plan"),cp=clone(src);cp.id=nid;cp.name=(src.id==="original_5day"?"My 5-Day Split":src.name)+" – My Copy";cp.locked=false;cp.source=src.id;customs[nid]=cp;save(K.customs,customs);activeProgramId=nid;localStorage.setItem(K.activeProgram,nid);toast("Personal copy created automatically");return nid
}

const ADD_BROWSER_GROUPS={
 muscle:["Chest","Shoulders","Biceps","Triceps","Forearms","Back","Glutes","Quadriceps","Hamstrings","Calves","Core","Abs","Traps","Adductors"],
 health:["Cardio","Mobility","Rehab"]
};
function browserIcon(mode){
 if(mode==="all")return '<svg viewBox="0 0 24 24"><path d="M12 3v18M3 12h18"/></svg>';
 if(mode==="muscle")return '<svg viewBox="0 0 24 24"><path d="M7 18c1-5 1-9 4-10 2 0 3 1 4 3 1-1 2-2 3-2 2 0 3 2 3 4 0 3-2 6-6 6H7Z"/></svg>';
 return '<svg viewBox="0 0 24 24"><path d="M12 21s-7-4.35-7-10a4 4 0 0 1 7-2.64A4 4 0 0 1 19 11c0 5.65-7 10-7 10Z"/></svg>';
}
function categoryInfo(name){
 const map={
  "Chest":{label:"Chest",muscle:"Mid Chest",desc:"Pressing and fly variations for upper, mid and lower chest."},
  "Shoulders":{label:"Shoulders",muscle:"Side Delts",desc:"Presses, lateral raises, rear-delt work and shoulder development."},
  "Biceps":{label:"Biceps",muscle:"Biceps",desc:"Curls emphasizing biceps brachii and arm flexion."},
  "Triceps":{label:"Triceps",muscle:"Triceps",desc:"Pushdowns, overhead extensions and press-based triceps work."},
  "Forearms":{label:"Forearms",muscle:"Forearms",desc:"Forearm flexors, grip strength and lower-arm detail."},
  "Back":{label:"Back",muscle:"Lats",desc:"Vertical pulls, rows and back-thickness exercises."},
  "Glutes":{label:"Glutes",muscle:"Glutes",desc:"Hip extension and glute-focused lower-body work."},
  "Quadriceps":{label:"Quadriceps",muscle:"Quads",desc:"Knee-dominant movements for front-thigh growth."},
  "Hamstrings":{label:"Hamstrings",muscle:"Hamstrings",desc:"Hip-hinge and leg-curl work for posterior chain."},
  "Calves":{label:"Calves",muscle:"Calves",desc:"Standing and seated plantar-flexion exercises."},
  "Core":{label:"Core",muscle:"Deep Core",desc:"Stability, anti-extension and trunk-control exercises."},
  "Abs":{label:"Abs",muscle:"Abs",desc:"Spinal flexion and lower-ab focused abdominal work."},
  "Traps":{label:"Traps",muscle:"Traps",desc:"Upper-trap and shrug-based movements."},
  "Adductors":{label:"Adductors",muscle:"Adductors",desc:"Inner-thigh and hip-adduction work."},
  "Cardio":{label:"Cardio",muscle:"Cardio",desc:"Conditioning and aerobic work."},
  "Mobility":{label:"Mobility",muscle:"Mobility",desc:"Mobility flows, yoga positions and range-of-motion work."},
  "Rehab":{label:"Rehab",muscle:"Rotator Cuff",desc:"Rotator cuff, shoulder health and controlled rehab work."}
 };
 return map[name]||{label:name,muscle:"Mobility",desc:name};
}
function libraryMatchesCategory(item,category){
 const L=lib(item.name||item),t=exerciseTargets(item.name||item),primary=L.primary||"",name=category;
 if(name==="Chest")return ["Upper Chest","Mid Chest","Lower Chest"].includes(t.primary)||primary==="Chest";
 if(name==="Shoulders")return ["Front Delts","Side Delts","Rear Delts"].includes(t.primary)||primary==="Shoulders"||primary==="Shoulder Health";
 if(name==="Biceps")return ["Biceps","Brachialis"].includes(t.primary)||primary==="Biceps";
 if(name==="Triceps")return String(t.primary).startsWith("Triceps")||primary==="Triceps";
 if(name==="Forearms")return ["Forearms","Grip"].includes(t.primary)||primary==="Forearms"||primary==="Grip";
 if(name==="Back")return ["Lats","Upper Back","Mid Back","Spinal Erectors"].includes(t.primary)||primary==="Back";
 if(name==="Glutes")return ["Glutes","Glute Medius"].includes(t.primary)||primary==="Glutes";
 if(name==="Quadriceps")return t.primary==="Quads"||primary==="Quads";
 if(name==="Hamstrings")return t.primary==="Hamstrings"||primary==="Hamstrings";
 if(name==="Calves")return t.primary==="Calves"||primary==="Calves";
 if(name==="Core")return t.primary==="Deep Core"||primary==="Core";
 if(name==="Abs")return t.primary==="Abs"||t.primary==="Abs (lower emphasis)"||primary==="Abs";
 if(name==="Traps")return t.primary==="Traps"||primary==="Traps";
 if(name==="Adductors")return t.primary==="Adductors"||primary==="Adductors";
 if(name==="Cardio")return L.kind==="cardio"||t.primary==="Cardio";
 if(name==="Mobility")return L.kind==="mobility"||t.primary==="Mobility";
 if(name==="Rehab")return t.primary==="Rotator Cuff"||primary==="Shoulder Health"||primary==="Rotator Cuff";
 return false;
}
function renderCategoryCards(mode){
 const cats=ADD_BROWSER_GROUPS[mode]||[];
 return `<div class="browserHeader"><h4>${mode==="muscle"?"Target Muscles":"Health & Performance"}</h4><span>${cats.length} categories</span></div><div class="categoryGrid">${cats.map(cat=>{const info=categoryInfo(cat),count=LIBRARY.filter(x=>libraryMatchesCategory(x,cat)).length;return `<button class="categoryCard" onclick="pickAddCategory('${cat.replace(/'/g,"\\'")}')"><div class="visual">${muscleSvg(info.muscle,true)}</div><div><b>${esc(info.label)}</b><small>${esc(info.desc)}</small><div class="count">${count} exercises</div></div><div class="chev">›</div></button>`}).join("")}</div>`;
}

window.openAddExercise=day=>{
 ensureEditable();activeDay=day;window.addBrowseMode="muscle";window.addBrowseCategory="";
 openModal("Add Exercise",`<div class="field"><label>Training day</label><select id="addDay" onchange="renderAddLibrary()">${DAYS.map(d=>`<option value="${d}" ${d===day?"selected":""}>${d} · ${esc(dayBlock(activeProgram(),d).name)}</option>`).join("")}</select></div><input class="search" id="addSearch" placeholder="Search ${LIBRARY.length} exercises..." oninput="renderAddLibrary()"><div class="browserTabs"><button class="" id="tabAll" onclick="setAddMode('all')">${browserIcon("all")}All</button><button class="active" id="tabMuscle" onclick="setAddMode('muscle')">${browserIcon("muscle")}Muscle</button><button class="" id="tabHealth" onclick="setAddMode('health')">${browserIcon("health")}Health</button></div><div id="addLib"></div><div class="secHead"><h3>Create Custom</h3></div><div class="field"><label>Exercise name</label><input id="customName" placeholder="My exercise"></div><div class="formRow"><div class="field"><label>Sets</label><input id="customSets" value="3"></div><div class="field"><label>Rep / time target</label><input id="customReps" value="8–12"></div></div><div class="field"><label>Machine / station</label><input id="customMachine"></div><button class="primary" onclick="addCustomExercise()">Add Custom Exercise</button>`);
 renderAddLibrary()
}
window.setAddMode=mode=>{window.addBrowseMode=mode;window.addBrowseCategory="";["tabAll","tabMuscle","tabHealth"].forEach(id=>$(id)?.classList.remove("active"));$(mode==="all"?"tabAll":mode==="muscle"?"tabMuscle":"tabHealth")?.classList.add("active");renderAddLibrary()}
window.pickAddCategory=cat=>{window.addBrowseCategory=cat;renderAddLibrary()}
window.clearAddCategory=()=>{window.addBrowseCategory="";renderAddLibrary()}
window.renderAddLibrary=()=>{
 let q=($("addSearch")?.value||"").trim().toLowerCase(),day=$("addDay")?.value||activeDay,dayName=dayBlock(activeProgram(),day).name.toLowerCase();
 let arr=LIBRARY.filter(x=>!q?true:(x.name+" "+x.equipment+" "+x.primary+" "+x.day).toLowerCase().includes(q));
 if(q){
  arr=arr.slice(0,80);
  $("addLib").innerHTML=`<div class="browserHeader"><h4>Search results</h4><span>${arr.length} matches</span></div>${arr.map(x=>{let t=exerciseTargets(x.name);return `<button class="swapItem visualItem" onclick="addFromLibrary('${esc(x.name).replace(/'/g,"\\'")}')"><div class="swapThumb">${muscleSvg(t.primary,true)}</div><div><b>${esc(x.name)}</b><small>Primary · ${esc(t.primary)} · ${esc(x.equipment)}</small></div></button>`}).join("")||'<div class="empty">No exercises found.</div>'}`;
  return;
 }
 const mode=window.addBrowseMode||"muscle",cat=window.addBrowseCategory||"";
 if((mode==="muscle"||mode==="health")&&!cat){$("addLib").innerHTML=renderCategoryCards(mode);return}
 if(mode==="all")arr=arr.filter(x=>x.day.toLowerCase().includes(activeProgram().category?.toLowerCase()||"")||x.primary.toLowerCase().includes(dayName.split(" ")[0])||x.day==="Abs & Core").slice(0,70);
 else if(cat)arr=arr.filter(x=>libraryMatchesCategory(x,cat)).slice(0,80);
 let header='';
 if(cat){const info=categoryInfo(cat);header=`<div class="browserHeader"><div><div class="filterPill">${esc(info.label)} <span class="x" onclick="clearAddCategory()">×</span></div><div class="inlineMeta">${esc(info.desc)}</div></div><span>${arr.length} exercises</span></div>`}
 else if(mode==="all")header=`<div class="browserHeader"><h4>Suggested for ${esc(dayBlock(activeProgram(),day).name)}</h4><span>${arr.length} exercises</span></div>`;
 $("addLib").innerHTML=`${header}${arr.map(x=>{let t=exerciseTargets(x.name);return `<button class="swapItem visualItem" onclick="addFromLibrary('${esc(x.name).replace(/'/g,"\\'")}')"><div class="swapThumb">${muscleSvg(t.primary,true)}</div><div><b>${esc(x.name)}</b><small>Primary · ${esc(t.primary)} · ${esc(x.equipment)}</small></div></button>`}).join("")||'<div class="empty">No exercises found in this category.</div>'}`
}
window.addFromLibrary=name=>{
 let d=$("addDay").value,p=activeProgram(),L=lib(name),sets=isTimedKind(L.kind)?1:3,reps=L.kind==="cardio"?"20 min":L.kind==="mobility"?"45–60 sec":L.kind==="compound"?"6–10":"10–15",rest=isTimedKind(L.kind)?0:(L.kind==="compound"?num(programCoach().compoundRest||150):num(programCoach().isolationRest||90));
 p.schedule[d].exercises.push({name,sets,reps,rest,priority:p.schedule[d].exercises.length+1,machine:"",notes:""});save(K.customs,customs);closeModal();renderAll();toast("Exercise added")
}
window.addCustomExercise=()=>{
 let d=$("addDay").value,name=$("customName").value.trim();if(!name)return toast("Enter an exercise name");let p=activeProgram();
 p.schedule[d].exercises.push({name,sets:Math.max(1,num($("customSets").value)||3),reps:$("customReps").value||"8–12",rest:90,priority:p.schedule[d].exercises.length+1,machine:$("customMachine").value||"",notes:""});save(K.customs,customs);closeModal();renderAll();toast("Custom exercise added")
}
window.openSwapPlan=(day,i)=>{ensureEditable();activeDay=day;window.swapIndex=i;window.swapMode="plan";let e=dayBlock(activeProgram(),day).exercises[i];openSwapModal(e)}
window.openSwap=i=>{window.swapIndex=i;window.swapMode="today";let e=currentExercises()[i];openSwapModal(e)}
function openSwapModal(e){
 let L=lib(e.name);window.swapCurrent=e;openModal("Swap "+e.name,`<p class="meta">Best matches use the same movement pattern first, then the same muscle, then the rest of the ${LIBRARY.length}-exercise library.</p><input class="search" id="swapSearch" placeholder="Search exercise or equipment..." oninput="renderSwapList()"><div id="swapList"></div>`);renderSwapList()
}
window.renderSwapList=()=>{
 let e=window.swapCurrent,L=lib(e.name),q=($("swapSearch")?.value||"").toLowerCase();
 let arr=LIBRARY.filter(x=>!q||(x.name+" "+x.equipment+" "+x.primary+" "+x.day).toLowerCase().includes(q));
 arr=arr.map(x=>({x,score:(x.pattern===L.pattern?0:x.primary===L.primary?1:x.day===L.day?2:3)})).sort((a,b)=>a.score-b.score||a.x.name.localeCompare(b.x.name)).slice(0,100);
 $("swapList").innerHTML=arr.map(({x,score})=>{let t=exerciseTargets(x.name);return `<button class="swapItem visualItem" onclick="chooseSwap('${esc(x.name).replace(/'/g,"\\'")}')"><div class="swapThumb">${muscleSvg(t.primary,true)}</div><div><b>${score===0?"★ ":""}${esc(x.name)}</b><small>${score===0?"Best pattern match":score===1?"Same muscle":score===2?"Same training category":"Alternative"} · Primary ${esc(t.primary)} · ${esc(x.equipment)}</small></div></button>`}).join("")
}
window.chooseSwap=name=>{
 const L=lib(name);
 if(window.swapMode==="today"){
  if(!requireWorkout())return;let e=activeWorkout.exercises[window.swapIndex];e.name=name;e.rest=isTimedKind(L.kind)?0:(L.kind==="compound"?num(programCoach().compoundRest||150):num(programCoach().isolationRest||90));e.rows=Array.from({length:Math.max(1,num(e.sets)||1)},()=>({weight:"",reps:"",rir:"",result:"",done:false}));save(K.activeWorkout,activeWorkout)
 }else{
  let p=activeProgram(),e=p.schedule[activeDay].exercises[window.swapIndex];e.name=name;e.rest=isTimedKind(L.kind)?0:(L.kind==="compound"?num(programCoach().compoundRest||150):num(programCoach().isolationRest||90));save(K.customs,customs)
 }
 closeModal();renderAll();toast("Exercise swapped")
}
window.editPlanExercise=(day,i)=>{
 ensureEditable();activeDay=day;let e=dayBlock(activeProgram(),day).exercises[i];window.editDay=day;window.editIndex=i;openModal("Edit Exercise",`<div class="field"><label>Exercise</label><input value="${esc(e.name)}" disabled></div><div class="formRow"><div class="field"><label>Sets</label><input id="editSets" value="${e.sets}"></div><div class="field"><label>Rep / time target</label><input id="editReps" value="${esc(e.reps)}"></div></div><div class="field"><label>Rest seconds</label><input id="editRest" value="${e.rest||0}"></div><div class="field"><label>Machine / station</label><input id="editMachine" value="${esc(machineMemory[e.name]?.machine||e.machine||"")}"></div><button class="primary" onclick="savePlanEdit()">Save</button><button class="danger" onclick="deletePlanExercise()">Delete Exercise</button>`)
}
window.savePlanEdit=()=>{
 let p=activeProgram(),e=p.schedule[window.editDay].exercises[window.editIndex];e.sets=Math.max(1,num($("editSets").value)||1);e.reps=$("editReps").value;e.rest=num($("editRest").value)||0;if(!machineMemory[e.name])machineMemory[e.name]={};machineMemory[e.name].machine=$("editMachine").value;save(K.machine,machineMemory);save(K.customs,customs);closeModal();renderAll();toast("Exercise updated")
}
window.deletePlanExercise=()=>{if(!confirm("Delete this exercise from this saved plan?"))return;let p=activeProgram();p.schedule[window.editDay].exercises.splice(window.editIndex,1);p.schedule[window.editDay].exercises.forEach((e,i)=>e.priority=i+1);save(K.customs,customs);closeModal();renderAll();toast("Exercise deleted")}
window.editToday=i=>{if(!requireWorkout())return;let e=activeWorkout.exercises[i];openModal("Edit Today",`<div class="field"><label>Exercise</label><input value="${esc(e.name)}" disabled></div><div class="formRow"><div class="field"><label>Sets</label><input id="todaySets" value="${e.sets}"></div><div class="field"><label>Rep / time target</label><input id="todayReps" value="${esc(e.reps)}"></div></div><button class="primary" onclick="saveTodayEdit(${i})">Save Today's Version</button>`)}
window.saveTodayEdit=i=>{let e=activeWorkout.exercises[i],sets=Math.max(1,num($("todaySets").value)||1);e.sets=sets;e.reps=$("todayReps").value;while(e.rows.length<sets)e.rows.push({weight:"",reps:"",rir:"",result:"",done:false});e.rows=e.rows.slice(0,sets);save(K.activeWorkout,activeWorkout);closeModal();renderAll()}

window.showTips=i=>{
 let e=currentExercises()[i],L=lib(e.name),r=recommendation(e),t=exerciseTargets(e),mem=machineMemory[e.name]||{};
 openModal(e.name,`<div class="detailHero"><div class="detailVisual">${muscleSvg(t.primary,false)}</div><div class="detailTargets"><div class="eyebrow">EXACT MUSCLE TARGET</div><b>${esc(t.primary)}</b><p>${esc((MUSCLE_INFO[t.primary]||{}).anatomy||t.primary)}</p><div class="chipRow"><span class="muscleChip primary">Primary · ${esc(t.primary)}</span>${t.secondary.map(s=>`<span class="muscleChip">${esc(s)}</span>`).join("")}</div></div></div><div class="detailSection"><h4>Why this exercise is here</h4><p>${esc(L.tip)}</p></div><div class="detailSection"><h4>Smart Coach</h4><p>${esc(r.msg)}</p><p style="margin-top:6px">${esc(r.last||"")}</p></div><div class="detailSection"><h4>Your machine setup</h4><p>${esc(mem.machine||e.machine||"No machine / seat saved yet.")}${mem.notes?`<br>${esc(mem.notes)}`:""}</p></div><button class="primary small" onclick="closeModal();showHistory(${i})">View exercise history</button>`)
}
window.showHistory=i=>{
 let e=currentExercises()[i],rows=[];for(const h of history){let x=(h.exercises||[]).find(y=>y.name===e.name);if(x?.sets?.length)rows.push({date:h.date,program:h.programName,x})}
 openModal(e.name+" History",rows.length?rows.slice(0,10).map(r=>`<div class="hist"><div class="histTop"><b>${new Date(r.date).toLocaleDateString()}</b><span>${esc(r.program||"")}</span></div><p>${r.x.sets.map((s,k)=>isTimedKind(lib(e.name).kind)?`Session: ${esc(s.result||e.reps)}`:`Set ${k+1}: ${s.weight}kg × ${s.reps} · RIR ${s.rir===""?"–":s.rir} · e1RM ${s.e1rm||0}`).join("<br>")}</p></div>`).join(""):'<div class="empty">No history yet.</div>')
}

function renderHistory(){
 $("historyCount").textContent=`${history.length} workouts`;$("historyList").innerHTML=history.length?history.map(h=>`<div class="hist"><div class="histTop"><b>${esc(h.programName||"Training")} · ${esc(h.name||h.day)}</b><span>${new Date(h.date).toLocaleDateString()}</span></div><div class="histStats"><span>TIME ${h.minutes||0} min</span><span>SETS ${h.sets||0}</span>${h.volume?`<span>VOLUME ${Number(h.volume).toLocaleString()} kg</span>`:""}<span>${esc(h.readiness||"")}</span></div><p>${esc(h.analysis||"")}</p></div>`).join(""):'<div class="empty">Complete your first workout to start history.</div>'
}
function weeklyVolume(){
 let m={};for(const d of DAYS)for(const e of effectivePlanExercises(d)){let L=lib(e.name);if(isTimedKind(L.kind))continue;m[L.primary]=(m[L.primary]||0)+num(e.sets)}return m
}
function renderProgress(){
 $("statWorkouts").textContent=history.length;$("statSets").textContent=history.reduce((a,h)=>a+num(h.sets),0);$("statVolume").textContent=Math.round(history.reduce((a,h)=>a+num(h.volume),0)/1000)+"k";
 let vm=weeklyVolume(),vals=Object.values(vm),mx=Math.max(1,...vals);$("volumeSummary").innerHTML=Object.keys(vm).length?Object.entries(vm).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="barRow"><span>${esc(k)}</span><div class="bar"><div class="fill" style="width:${v/mx*100}%"></div></div><b>${v}</b></div>`).join(""):'<div class="empty">No resistance sets in this program.</div>';
 let best={};for(const h of history)for(const e of h.exercises||[])for(const s of e.sets||[]){let x=e1rm(s.weight,s.reps);if(x>(best[e.name]||0))best[e.name]=x}
 $("prList").innerHTML=Object.keys(best).length?Object.entries(best).sort((a,b)=>b[1]-a[1]).slice(0,30).map(([k,v])=>`<div class="hist"><div class="histTop"><b>${esc(k)}</b><span>e1RM ${v} kg</span></div></div>`).join(""):'<div class="empty">PR estimates appear after resistance workouts.</div>'
}

function openModal(title,body){$("modalTitle").textContent=title;$("modalBody").innerHTML=body;$("modalOverlay").classList.add("show")}
window.closeModal=()=>$("modalOverlay").classList.remove("show")
window.openBackup=()=>openModal("Backup & Data",`<p class="meta">All data is stored locally on this device. Export a backup before clearing Safari data or changing phones.</p><button class="primary" onclick="exportBackup()">Export Backup</button><div class="field"><label>Import backup JSON</label><input type="file" id="importFile" accept=".json,application/json"></div><button class="primary small" onclick="importBackup()">Import Backup</button>`)
window.exportBackup=()=>{
 let data={customs,activeProgramId,history,machineMemory,addonState,prefs};let blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="AJ-Training-v5-backup.json";a.click();URL.revokeObjectURL(a.href)
}
window.importBackup=()=>{
 let f=$("importFile").files[0];if(!f)return toast("Choose a backup file");let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);customs=x.customs||customs;activeProgramId=x.activeProgramId||activeProgramId;history=x.history||history;machineMemory=x.machineMemory||machineMemory;addonState=x.addonState||addonState;prefs=Object.assign(prefs,x.prefs||{});save(K.customs,customs);localStorage.setItem(K.activeProgram,activeProgramId);save(K.history,history);save(K.machine,machineMemory);save(K.addons,addonState);save(K.prefs,prefs);closeModal();renderAll();toast("Backup imported")}catch(e){toast("Invalid backup file")}};r.readAsText(f)
}
window.nav=b=>{document.querySelectorAll(".nav button").forEach(x=>x.classList.remove("active"));b.classList.add("active");document.querySelectorAll(".panel").forEach(x=>x.classList.remove("active"));$(b.dataset.id).classList.add("active");renderAll()}
function renderAll(){renderWeek();renderHero();renderExercises();renderPrograms();renderHistory();renderProgress()}
renderAll();
if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./service-worker.js").catch(()=>{}));
